import math
def control(obs):
    h=obs['hitch_deg']
    a=math.radians(h)
    cam=obs.get('views',{}).get('camera')
    err=0.0
    if cam and cam.get('walls'):
        ox,oy=cam['origin']; rx,ry=obs['rig']['trailer_rear']
        groups=[[]]; last=None
        for b,d in cam['walls']:
            b=math.radians(b)
            x=ox+d*math.cos(b)-rx; y=oy+d*math.sin(b)-ry
            p=(-x*math.cos(a)+y*math.sin(a),x*math.sin(a)+y*math.cos(a))
            if last and math.hypot(p[0]-last[0],p[1]-last[1])>2.8: groups.append([])
            groups[-1].append(p); last=p
        groups=sorted(groups,key=len,reverse=True)[:2]
        ys=[]
        for g in groups:
            pts=sorted(g)
            for (s,y),(t,z) in zip(pts,pts[1:]):
                if s<=3.0<=t and t>s:
                    ys.append(y+(z-y)*(3.0-s)/(t-s)); break
        if len(ys)==2: err=math.degrees(math.atan2(sum(ys)/2,3.0))
    steer=max(-34,min(34,0.75*h-2.1*err))
    return steer,-0.5,-23

