import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        sides=[[],[]]
        th=math.radians(obs['rig']['trailer_heading_deg'])
        for b,d in cam.get('walls',[]):
            a=math.radians(b)-th
            s=-d*math.cos(a); y=d*math.sin(a)
            if 2<s<13 and abs(y)>1.5:
                sides[0 if y>0 else 1].append((s,y))
        vals=[]
        for pts in sides:
            if len(pts)>=3:
                n=len(pts); sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
                den=sum(p[0]**2 for p in pts)-sx*sx/n
                m=(sum(x*y for x,y in pts)-sx*sy/n)/max(den,0.1)
                vals.append(sy/n+m*(9-sx/n))
        if len(vals)==2:
            offset=sum(vals)/2
            desired=max(-28,min(28,math.degrees(math.atan2(20.4*offset,81))))
    steer=2.0*(h-desired)+math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))
    return (max(-42,min(42,steer)), -1.3, -41)

